import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/GET-DATA.md","filePath":"manual-zh/GET-DATA.md","lastUpdated":1785684581000}'),d={name:"manual-zh/GET-DATA.md"};function p(n,t,T,c,l,h){return r(),a("div",null,[...t[0]||(t[0]=[o(`<h3 id="_9-4-get-data" tabindex="-1">9.4 GET DATA <a class="header-anchor" href="#_9-4-get-data" aria-label="Permalink to &quot;9.4 GET DATA&quot;">​</a></h3><pre><code>GET DATA
        /TYPE={GNM,ODS,PSQL,TXT}
        …additional subcommands depending on TYPE…
</code></pre><p><code>GET DATA</code> 命令用于读取由其他应用程序创建的文件和其他数据源。执行此命令时，当前字典和活动数据集会被从指定源读取的变量和数据替换。</p><p><code>TYPE</code> 子命令是必需的，并且必须是第一个指定的子命令。它决定要读取的文件或源的类型。PSPP 目前支持以下文件类型：</p><p>GNM</p><p>Gnumeric 创建的电子表格文件 (<a href="http://gnumeric.org" target="_blank" rel="noreferrer">http://gnumeric.org</a>)。</p><p>ODS</p><p>OpenDocument 格式的电子表格文件 (<a href="http://opendocumentformat.org" target="_blank" rel="noreferrer">http://opendocumentformat.org</a>)。</p><p>PSQL</p><p>来自 PostgreSQL 数据库的关系 (<a href="http://postgresql.org" target="_blank" rel="noreferrer">http://postgresql.org</a>)。</p><p>TXT</p><p>以列式和分隔格式存储的文本数据文件。</p><p>每种支持的文件类型都有额外的子命令，在下方的单独小节中说明。</p><table tabindex="0"><thead><tr><th>• GET DATA /TYPE=GNM/ODS</th><th></th><th>电子表格</th></tr></thead><tbody><tr><td>• GET DATA /TYPE=PSQL</td><td></td><td>数据库</td></tr><tr><td>• GET DATA /TYPE=TXT</td><td></td><td>分隔文本文件</td></tr></tbody></table>`,14)])])}const A=e(d,[["render",p]]);export{_ as __pageData,A as default};
